Lemma aconst_ok_high : forall lo hi, sh AIMG_TOP <= lo ->
  (hi <= 0x17c000 \/ 0x6e5908 <= lo
   \/ (0x6b1d50 <= lo /\ hi <= 0x6c3ec0) \/ (0x6c3f48 <= lo /\ hi <= 0x6e53d0) \/ (0x6e53d8 <= lo /\ hi <= 0x6e5908)) ->
