Lemma ACONST_read_stage : forall m, ACONST m -> addressable m AREAD_STAGE 65536.
Proof.
  intros m H. apply (ACONST_global_addressable m AREAD_STAGE 65536 65536 H); [|lia].
  unfold aglobals, AREAD_STAGE. repeat (first [left; reflexivity | right]).
Qed.

